skins.css:
/* Abyssal Serenade for Artflow. This is a scoped adaptation, not the dsh stylesheet.
 * The SkinEngine substitutes builtin.skin-abyssal-light and the locally bundled backdrop.
 * Every selector is scoped so the existing skin sanitizer can validate this file.
 */

[data-bp-skin-active="builtin.skin-abyssal-light"] {
  --bp-abyssal-dialog: rgba(249,253,254,0.93);
  --bp-abyssal-section: rgba(241,249,251,0.90);
  --bp-abyssal-soft: rgba(24,158,180,0.10);
  --bp-abyssal-on-accent: #052735;
  --bp-abyssal-bubble: rgba(69,172,194,0.35);
  --bp-abyssal-bubble-border: rgba(64,160,181,0.33);
  --bp-abyssal-bubble-shadow: rgba(70,175,196,0.27);
  --bp-abyssal-scrollbar: rgba(15,43,64,0.24);
  --bp-abyssal-scrollbar-hover: rgba(24,158,180,0.44);
}

/* App uses the wallpaper variable ONLY when this board has no user-set background.
 * Therefore personal board wallpapers and presentation's black background keep priority.
 */
[data-bp-skin-active="builtin.skin-abyssal-light"] #root {
  --bp-canvas-bg-image: linear-gradient(rgba(244,250,252,0.10), rgba(233,244,247,0.26)), url('data:image/webp;base64,');
}

[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-wallpaper="off"] #root {
  --bp-canvas-bg-image: var(--bp-canvas-bg);
}

/* 上浮气泡：纯 CSS 背景层，零 JS 零 DOM（声明式替代原内置 widget）。
 * 4 个伪元素组 × 4 颗 = 16 颗；各组时长/相位/漂移方向不同，错峰上浮。
 * 开关由声明式 attributeBindings（showBubbles → data-bp-abyssal-bubbles）投影到
 * documentElement，这里只按属性值门控；切皮肤时引擎按追踪清单清理属性。 */
[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::before,
[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::after,
[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::before,
[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 2;
  overflow: hidden;
  pointer-events: none;
  contain: layout style paint;
  background-repeat: no-repeat;
  opacity: 0;
  will-change: transform, opacity;
}

[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::before {
  background-image:
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%);
  background-size: 4px 4px, 4px 4px, 7px 7px, 7px 7px, 10px 10px, 10px 10px, 5px 5px, 5px 5px;
  background-position: 14% 106%, 14% 106%, 37% 106%, 37% 106%, 63% 106%, 63% 106%, 86% 106%, 86% 106%;
  animation: bp-abyssal-rise-a 13s linear 0s infinite;
}

@keyframes bp-abyssal-rise-a {
  0% { transform: translate3d(0, 10vh, 0); opacity: 0; }
  10% { opacity: .55; }
  70% { opacity: .32; }
  100% { transform: translate3d(1.2vw, -116vh, 0); opacity: 0; }
}

[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::after {
  background-image:
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%);
  background-size: 6px 6px, 6px 6px, 10px 10px, 10px 10px, 4px 4px, 4px 4px, 7px 7px, 7px 7px;
  background-position: 9% 106%, 9% 106%, 31% 106%, 31% 106%, 57% 106%, 57% 106%, 81% 106%, 81% 106%;
  animation: bp-abyssal-rise-b 16s linear -5s infinite;
}

@keyframes bp-abyssal-rise-b {
  0% { transform: translate3d(0, 10vh, 0); opacity: 0; }
  10% { opacity: .55; }
  70% { opacity: .32; }
  100% { transform: translate3d(-1.6vw, -116vh, 0); opacity: 0; }
}

[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::before {
  background-image:
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%);
  background-size: 5px 5px, 5px 5px, 8px 8px, 8px 8px, 6px 6px, 6px 6px, 4px 4px, 4px 4px;
  background-position: 21% 106%, 21% 106%, 44% 106%, 44% 106%, 69% 106%, 69% 106%, 92% 106%, 92% 106%;
  animation: bp-abyssal-rise-c 11s linear -9s infinite;
}

@keyframes bp-abyssal-rise-c {
  0% { transform: translate3d(0, 10vh, 0); opacity: 0; }
  10% { opacity: .55; }
  70% { opacity: .32; }
  100% { transform: translate3d(0.8vw, -116vh, 0); opacity: 0; }
}

[data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::after {
  background-image:
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%),
    radial-gradient(circle, transparent 58%, var(--bp-abyssal-bubble-border) 61%, transparent 64%),
    radial-gradient(circle at 30% 27%, rgba(255,255,255,0.68), var(--bp-abyssal-bubble) 42%, transparent 79%);
  background-size: 9px 9px, 9px 9px, 4px 4px, 4px 4px, 6px 6px, 6px 6px, 10px 10px, 10px 10px;
  background-position: 6% 106%, 6% 106%, 25% 106%, 25% 106%, 47% 106%, 47% 106%, 73% 106%, 73% 106%;
  animation: bp-abyssal-rise-d 18s linear -13s infinite;
}

@keyframes bp-abyssal-rise-d {
  0% { transform: translate3d(0, 10vh, 0); opacity: 0; }
  10% { opacity: .55; }
  70% { opacity: .32; }
  100% { transform: translate3d(-1.1vw, -116vh, 0); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  [data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::before,
  [data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] body::after,
  [data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::before,
  [data-bp-skin-active="builtin.skin-abyssal-light"][data-bp-abyssal-bubbles="on"] #root::after {
    animation: none;
    opacity: .22;
    transform: translate3d(0, -48vh, 0);
  }
}

/* Artflow's existing panel shells are dark-coded; retheme only these explicit
 * host surfaces. Other skins retain their original appearance and behavior.
 */
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-dialog);
  backdrop-filter: blur(18px) saturate(1.12);
  -webkit-backdrop-filter: blur(18px) saturate(1.12);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings-nav] > div,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-section] {
  background-color: var(--bp-abyssal-section);
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-section] > button {
  color: var(--bp-text-primary);
  background-color: var(--bp-abyssal-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-section] > button:hover {
  background-color: var(--ui-hover);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-segmented] {
  background-color: var(--bp-abyssal-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-segmented] [data-bp-ui-active="true"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings-nav] [data-bp-ui-active="true"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="bg-violet-500"] {
  background-color: var(--bp-accent);
  color: var(--bp-abyssal-on-accent);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-white"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-neutral-100"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-neutral-200"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] [class~="text-white"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] [class~="text-neutral-200"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [class~="text-white"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [class~="text-neutral-200"] {
  color: var(--bp-text-primary);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-neutral-300"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-neutral-400"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-neutral-500"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] [class~="text-gray-400"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] [class~="text-neutral-300"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] [class~="text-neutral-400"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [class~="text-neutral-300"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [class~="text-neutral-400"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [class~="text-neutral-500"] {
  color: var(--bp-text-muted);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] input:not([type="checkbox"]),
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] select,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] textarea,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] input {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-section);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] input::placeholder,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] input::placeholder {
  color: var(--bp-text-muted);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel-entry] {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-section);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel-entry]:hover,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] [data-bp-ui-active="true"] {
  color: var(--bp-text-primary);
  border-color: var(--bp-accent);
  background-color: var(--bp-accent-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel-entry] > span:first-child {
  color: var(--bp-accent);
  background-color: var(--bp-accent-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel-entry] [class~="text-sky-200"] {
  color: var(--bp-accent);
}

/* The theme library previews each candidate's colors in its thumbnail, but
 * its labels and controls must remain readable in the CURRENT host palette.
 */
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > p:first-child,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > ul > li > button,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > section {
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-section);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > ul > li > button:hover {
  border-color: var(--bp-accent);
  background-color: var(--bp-abyssal-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > ul > li > button[aria-pressed="true"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] > section[aria-label^="皮肤设置"] {
  border-color: var(--bp-accent);
  background-color: var(--bp-accent-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="text-teal-100"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="text-teal-200"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="text-sky-100"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="text-fuchsia-100"] {
  color: var(--bp-text-primary);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [data-bp-ui-skin-tag],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="rounded-full"][class~="text-teal-100"],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] [class~="rounded-full"][class~="text-sky-100"] {
  color: var(--bp-text-primary);
  background-color: var(--bp-abyssal-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] input:not([type="checkbox"]),
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] select {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-skin-picker] select option {
  color: var(--bp-text-primary);
  background-color: var(--bp-abyssal-section);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] kbd {
  color: var(--bp-text-muted);
  background-color: var(--bp-abyssal-section);
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] :focus-visible,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] :focus-visible,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] :focus-visible {
  outline: 2px solid var(--bp-accent);
  outline-offset: 2px;
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] *::-webkit-scrollbar,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] *::-webkit-scrollbar,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] *::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] *::-webkit-scrollbar-thumb,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] *::-webkit-scrollbar-thumb,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] *::-webkit-scrollbar-thumb {
  border-radius: 8px;
  background: var(--bp-abyssal-scrollbar);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-settings] *::-webkit-scrollbar-thumb:hover,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-panel] *::-webkit-scrollbar-thumb:hover,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-command] *::-webkit-scrollbar-thumb:hover {
  background: var(--bp-abyssal-scrollbar-hover);
}

/* The three always-visible workspace widgets also need to follow the light
 * palette. Stable data markers avoid styling unrelated plugin content.
 */
[data-bp-skin-active="builtin.skin-abyssal-light"] #root {
  --bp-abyssal-prompt-action: var(--bp-accent);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-dock],
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-panel] {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
  background-color: var(--bp-abyssal-dialog);
  backdrop-filter: blur(18px) saturate(1.12);
  -webkit-backdrop-filter: blur(18px) saturate(1.12);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-dock]:hover {
  border-color: var(--bp-accent);
  background-color: var(--bp-abyssal-section);
}

/* Keep both lower corners clear of the prompt, and keep the detail sheet
 * above the raised workspace entry without overflowing shorter windows. */
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-dock] {
  bottom: 6rem;
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-panel] {
  bottom: 11.5rem;
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-panel] > div:last-child {
  max-height: min(38rem, calc(100vh - 15.5rem));
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] {
  width: min(19rem, calc(100vw - 2rem));
  bottom: 6rem; /* keep its footer above the prompt bar on ordinary windows */
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] > header {
  flex-wrap: wrap;
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] > header > div:last-child {
  flex-wrap: wrap;
  max-width: 100%;
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] button {
  color: var(--bp-text-primary);
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] button:last-child {
  color: var(--bp-accent);
  background-color: var(--bp-accent-soft);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] svg[aria-label] {
  color: var(--bp-text-primary);
  background-color: var(--bp-abyssal-section);
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] svg[aria-label] text {
  fill: var(--bp-text-muted);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-navigator] header,
[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-panel] header {
  border-color: var(--ui-border);
}

[data-bp-skin-active="builtin.skin-abyssal-light"] [data-bp-ui-workspace-dock] > span:first-child {
  color: var(--bp-accent);
